const glossary: HelpContentModule["glossary"] = [
  { id: "http-method", term: "HTTP method", short: "The verb of a request: it says what you want to do. GET reads data. POST sends data to create something. The Studio uses GET and POST.", section: "api-learning", keywords: ["get", "post", "put", "delete"] },
  { id: "get-vs-post", term: "GET vs POST", short: "GET asks for data and should not change anything, so repeating it is safe. POST sends a body to create or change something, so repeating it can create duplicates.", section: "api-learning" },
  { id: "status-code-2xx-4xx-5xx", term: "Status code (2xx, 4xx, 5xx)", short: "A three-digit number in the response. 2xx means success, 4xx means the request was wrong (fix it), and 5xx means the server failed (often worth retrying).", more: "Examples: 200 OK, 201 Created, 400 Bad Request, 401 Unauthorized, 403 Forbidden, 404 Not Found, 429 Too Many Requests, 500 Internal Server Error.", section: "api-learning", keywords: ["200", "404", "429", "500"] },
  { id: "request-header", term: "Request header", short: "A name and value sent along with a request, such as Accept, Content-Type or Authorization. Headers describe the request instead of being the data.", section: "api-learning" },
  { id: "query-parameter", term: "Query parameter", short: "A name and value added to the end of a URL after a question mark, like page=2. It narrows or pages the result.", section: "api-learning", keywords: ["querystring", "page", "limit"] },
  { id: "request-body", term: "Request body", short: "The data you send with a POST, usually as JSON, such as the item and quantity of an order. A GET normally has no body.", section: "api-learning" },
  { id: "bearer-token", term: "Bearer token", short: "A secret string sent in the Authorization header as Bearer and the token. Whoever holds it is treated as the user, so keep it private. Missing or expired tokens get a 401.", section: "api-learning", keywords: ["authorization", "authentication", "token"] },
  { id: "json", term: "JSON", short: "A plain-text format for data: objects with names and values, and lists. APIs send and receive it, and your program parses it into dictionaries and lists.", section: "api-learning" },
  { id: "pagination", term: "Pagination", short: "Returning a large result in pages instead of all at once. You keep asking for the next page until the server says there are no more.", section: "api-learning", keywords: ["pages", "paging"] },
  { id: "cursor-pagination", term: "Cursor pagination", short: "Each page ends with a cursor that marks the last record. You send it back to get the rows after it. It stays correct when new rows arrive in between.", section: "api-learning", keywords: ["next_cursor"] },
  { id: "rate-limit", term: "Rate limit", short: "A cap on how many requests you may send in a time window. Go over and the server answers 429 Too Many Requests until you slow down.", section: "api-learning", keywords: ["429", "throttle"] },
  { id: "retry-after", term: "Retry-After", short: "A response header that says how many seconds to wait before trying again. If it is present, wait that long instead of guessing.", section: "api-learning" },
  { id: "exponential-backoff", term: "Exponential backoff", short: "Waiting longer after each failed try: for example 200, 400, 800 milliseconds. It gives a struggling server time to recover and stops you flooding it.", section: "api-learning", keywords: ["retry", "backoff"] },
  { id: "idempotency-key", term: "Idempotency-Key", short: "A unique value sent with a POST. If the same key arrives twice, the server returns the first result instead of creating a second record. It makes retries safe.", section: "api-learning", keywords: ["idempotent", "duplicate"] },
  { id: "series-vs-dataframe", term: "Series vs DataFrame", short: "A Series is a single labelled column of values. A DataFrame is a table of several columns that share the same row labels.", section: "pandas" },
  { id: "groupby", term: "GroupBy", short: "Splits rows into groups by a column's values, then combines each group into one result, such as a sum or an average. It works like SQL GROUP BY.", section: "pandas", keywords: ["group by", "aggregate"] },
  { id: "merge-join", term: "Merge (join)", short: "Combines two tables by matching a key column. A left merge keeps every row from the left table and fills NaN where the right table has no match.", section: "pandas", keywords: ["join", "left join", "inner"] },
  { id: "missing-values-nan", term: "Missing values (NaN)", short: "NaN marks a value that is not there. It appears when data is absent, a merge finds no match, or a conversion fails. You can fill it or drop those rows.", section: "pandas", keywords: ["nan", "null", "none", "fillna", "dropna"] },
  { id: "ndarray", term: "ndarray", short: "NumPy's array: a grid of numbers that all share one type. Whole-array operations run on every element at once.", section: "numpy", keywords: ["numpy array", "array"] },
  { id: "array-shape", term: "Array shape", short: "The size of each dimension, as a tuple. A shape of (2, 3) means 2 rows and 3 columns.", section: "numpy", keywords: ["shape", "dimensions", "ndim"] },
  { id: "axis", term: "Axis", short: "The direction an operation works along. In a 2-D array, axis=0 goes down the rows (one result per column) and axis=1 goes across (one result per row).", section: "numpy", keywords: ["axis=0", "axis=1"] },
  { id: "broadcasting", term: "Broadcasting", short: "NumPy stretches a smaller array to match a larger one so they can be combined, for example adding a row of 3 numbers to every row of a (2, 3) array.", section: "numpy", keywords: ["stretch", "shape mismatch"] },
  { id: "vectorization", term: "Vectorization", short: "Writing one operation that works on a whole array instead of looping over each item. It is shorter and usually much faster.", section: "numpy", keywords: ["vectorised", "loop"] },
  { id: "slicing", term: "Slicing", short: "Picking part of a sequence or array with start:stop, such as x[0, :] for the first row. A slice of an array is a smaller array.", section: "numpy", keywords: ["indexing", "slice"] },
  { id: "chart-dimension-vs-measure", term: "Dimension vs measure", short: "A dimension is a label you group by, like region or month. A measure is a number you total up, like revenue. Charts show a measure per dimension value.", section: "data-visualization" },
  { id: "aggregation", term: "Aggregation", short: "Combining many rows into one number per group: sum, average (avg), count, min or max. The choice changes what a chart says.", section: "data-visualization", keywords: ["sum", "avg", "count"] },
  { id: "call-stack", term: "Call stack", short: "The list of functions that are running right now. Calling a function adds a row on top; returning removes it. Recursion makes the stack grow.", section: "python-time-machine", keywords: ["stack", "frame"] },
  { id: "trace-step", term: "Trace step", short: "One recorded moment of a program run: a line about to run, a call, a return or an error. The playback bar moves through these steps.", section: "python-time-machine", keywords: ["step", "trace"] },
  { id: "provenance-badge", term: "Provenance badge", short: "A small label on a visual that tells you how real it is: Executed (really ran), Parsed, Plan, Estimated, Conceptual model or Simulated.", section: "visual-hub", keywords: ["executed", "simulated", "conceptual"] },
];

